  --secondary: rgb(58, 49, 40);
  --secondary-foreground: rgb(252, 223, 194);
  --muted: rgb(34, 34, 34);
  --muted-foreground: rgb(180, 180, 180);
  --accent: rgb(43, 43, 43);
  --accent-foreground: rgb(238, 238, 238);
  --destructive: rgb(229, 80, 50);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(33, 31, 26);
  --input: rgb(72, 72, 72);
  --ring: rgb(252, 223, 194);
  --chart-1: rgb(252, 223, 194);
  --chart-2: rgb(58, 49, 40);
  --chart-3: rgb(43, 43, 43);
  --chart-4: rgb(66, 57, 48);
  --chart-5: rgb(252, 223, 194);
  --radius: 0.5rem;
  --sidebar: rgb(24, 24, 29);
